mapper.sql:
WITH TEMP_RANGE_YIELD AS ( SELECT A.PORTFOLIO_ID, B.FINPROD_ID, D.RANGE_YIELD * 100 RANGE_YIELD FROM PTL_SEC_POSITION A, FIN_PRODUCT B, FIN_CASH_INFO C, FIN_CASH_PLAN D WHERE A.HODING_TYPE = '03' AND A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = C.FINPROD_ID AND C.CASH_ID = D.CASH_ID AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd') AND D.VDATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') AND D.MDATE >= TO_DATE(#{queryDate},'YYYY-MM-DD') AND B.FINPROD_TYPE2 IN ( 'F01', 'F17', 'F18' ) UNION ALL SELECT A.PORTFOLIO_ID, B.FINPROD_ID, D.YIELD * 100 RANGE_YIELD FROM PTL_SEC_POSITION A, FIN_PRODUCT B, FIN_CASH_INFO C, FIN_CASH_CALC_RULE D WHERE A.HODING_TYPE = '03' AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd') AND A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = C.FINPROD_ID AND C.CASH_ID = D.CASH_ID AND C.CASH_TYPE_2 = 'C02' AND B.FINPROD_TYPE2 = 'F07' AND D.EFF_DATE = B.VDATE ),
TEMP_LAST_MDATE AS ( SELECT A.PORTFOLIO_ID, B.FINPROD_ID, MAX( C.TRADE_DATE ) TRADE_DATE FROM PTL_SEC_POSITION A, FIN_PRODUCT B, TRD_PRODUCT_DEAL C WHERE A.HODING_TYPE = '03' AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd') AND A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ( 'F01', 'F07', 'F17', 'F18' ) AND A.FINPROD_ID = C.FINPROD_ID AND C.PS = 'T09' GROUP BY A.PORTFOLIO_ID, B.FINPROD_ID ),
TEMP_DEPT_CODE AS ( SELECT PORTFOLIO_ID, FINPROD_ID, to_char(wm_concat ( DEPT_CODE )) DEPT_CODE FROM ( SELECT DISTINCT A.PORTFOLIO_ID, B.FINPROD_ID, D.DEPT_CODE FROM PTL_SEC_POSITION A, FIN_PRODUCT B, PTL_SEC_POSITION_FLOW C, PA_TRD_PRODUCT_DEAL D WHERE A.HODING_TYPE = '03' AND A.FINPROD_ID = B.FINPROD_ID AND A.PORTFOLIO_ID = C.PORTFOLIO_ID AND A.FINPROD_ID = C.FINPROD_ID AND C.TRADE_ID = D.TRADE_ID AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND (D.DEPT_CODE in
null) or D.DEPT_CODE in (
#{item}
)
) AA GROUP BY AA.PORTFOLIO_ID, AA.FINPROD_ID ),
TEMP_CLOSE_PRICE AS ( SELECT D.PORTFOLIO_ID, D.FINPROD_ID, E.CLOSE_PRICE FROM MST_BOND_MARKET_INFO E, ( SELECT A.PORTFOLIO_ID, B.FINPROD_ID, B.FINPROD_MARKET_ID, MAX( C.VALUE_DATE ) VALUE_DATE FROM PTL_SEC_POSITION A, FIN_PRODUCT B, MST_BOND_MARKET_INFO C WHERE A.HODING_TYPE = '03' AND A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ( 'F01' ) AND B.FINPROD_MARKET_ID = C.SEC_ID AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd') AND C.VALUE_DATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') GROUP BY A.PORTFOLIO_ID, B.FINPROD_ID, B.FINPROD_MARKET_ID ) D WHERE E.SEC_ID = D.FINPROD_MARKET_ID AND E.VALUE_DATE = D.VALUE_DATE UNION ALL SELECT D.PORTFOLIO_ID, D.FINPROD_ID, E.VALUATION CLOSE_PRICE FROM FIN_PRODUCT_VALUATION E, ( SELECT A.PORTFOLIO_ID, B.FINPROD_ID, MAX( C.VAL_DATE ) VAL_DATE FROM PTL_SEC_POSITION A, FIN_PRODUCT B, FIN_PRODUCT_VALUATION C WHERE A.HODING_TYPE = '03' AND A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ( 'F06', 'F17' ) AND B.FINPROD_ID = C.FINPROD_ID AND A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd') AND C.VAL_DATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') GROUP BY A.PORTFOLIO_ID, B.FINPROD_ID ) D WHERE E.FINPROD_ID = D.FINPROD_ID AND E.VAL_DATE = D.VAL_DATE )

SELECT A.PORTFOLIO_ID, C.FINPROD_ID, '' PORTFOLIO_NAME, '' FINPROD_TYPE2, '' TYPE_4, D.TYPE_5, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, G.CUSTOMER_NAME ISSUER, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE, SUM( A.AMOUNT ) AMOUNT, '02' hasChildren, CONCAT(CONCAT(nvl(A.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl(D.TYPE_4,'null'),'_'),nvl(D.TYPE_5,'null')))) childInfo, CONCAT(CONCAT(A.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),nvl(D.TYPE_4,'null'))) parentInfo FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 = 'F01' INNER JOIN FIN_PRODUCT_TYPE D ON C.FINPROD_ID = D.FINPROD_ID INNER JOIN FIN_CASH_INFO E ON E.CASH_TYPE_2 = 'C02' AND E.FINPROD_ID = C.FINPROD_ID INNER JOIN FIN_CASH_CALC_RULE F ON E.CASH_ID = F.CASH_ID AND F.EFF_DATE = C.VDATE LEFT JOIN TEMP_RANGE_YIELD TEMP_RANGE_YIELD ON TEMP_RANGE_YIELD.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_RANGE_YIELD.FINPROD_ID = A.FINPROD_ID LEFT JOIN TEMP_LAST_MDATE TEMP_LAST_MDATE ON TEMP_LAST_MDATE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_LAST_MDATE.FINPROD_ID = A.FINPROD_ID
LEFT JOIN TEMP_CLOSE_PRICE TEMP_CLOSE_PRICE ON TEMP_CLOSE_PRICE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_CLOSE_PRICE.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO G ON C.ISSUER = G.CUSTOMER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND C.FINPROD_TYPE2 in
#{item}
AND D.TYPE_4 in
#{item}
AND D.TYPE_5 in
#{item}
GROUP BY A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_4, D.TYPE_5, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, G.CUSTOMER_NAME, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE
union all SELECT A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6 TYPE_4, D.TYPE_7 TYPE_5, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, I.COUNTER_NAME ISSUER, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, null CLOSE_PRICE, SUM( A.AMOUNT ) AMOUNT, '02' hasChildren, CONCAT(CONCAT(nvl(A.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl(D.TYPE_6,'null'),'_'),nvl(D.TYPE_7,'null')))) childInfo, CONCAT(CONCAT(A.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),nvl(D.TYPE_6,'null'))) parentInfo FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 = 'F07' INNER JOIN FIN_PRODUCT_TYPE D ON C.FINPROD_ID = D.FINPROD_ID INNER JOIN FIN_CASH_INFO E ON E.CASH_TYPE_2 = 'C02' AND E.FINPROD_ID = C.FINPROD_ID INNER JOIN FIN_CASH_CALC_RULE F ON E.CASH_ID = F.CASH_ID AND F.EFF_DATE = C.VDATE left join PA_FIN_PRODUCT H on H.FINPROD_ID = A.FINPROD_ID left join MST_COUNTER_PARTY I on I.COUNTER_ID = H.ASSET_PROVIDER LEFT JOIN TEMP_RANGE_YIELD TEMP_RANGE_YIELD ON TEMP_RANGE_YIELD.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_RANGE_YIELD.FINPROD_ID = A.FINPROD_ID LEFT JOIN TEMP_LAST_MDATE TEMP_LAST_MDATE ON TEMP_LAST_MDATE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_LAST_MDATE.FINPROD_ID = A.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO G ON C.ISSUER = G.CUSTOMER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND C.FINPROD_TYPE2 in
#{item}
AND D.TYPE_6 in
#{item}
AND D.TYPE_7 in
#{item}
GROUP BY A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6, D.TYPE_7, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, I.COUNTER_NAME, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE
union all select AA.PORTFOLIO_ID, AA.FINPROD_ID, AA.PORTFOLIO_NAME, AA.FINPROD_TYPE2, '' TYPE_4, '' TYPE_5, AA.FINPROD_MARKET_ID, AA.FINPROD_ABBR, AA.VDATE, AA.MDATE, AA.BASIS, AA.ISSUER, AA.CCY, AA.RANGE_YIELD, AA.TRADE_DATE, AA.DEPT_CODE, null CLOSE_PRICE, sum(AA.AMOUNT) AMOUNT, '02' hasChildren, CONCAT(CONCAT(nvl(AA.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(AA.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl('','null'),'_'),null))) childInfo, CONCAT(CONCAT(AA.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(AA.FINPROD_TYPE2,'null'),'_'),null)) parentInfo from ( SELECT A.PORTFOLIO_ID, A.FINPROD_ID, B.PORTFOLIO_NAME, D.FINPROD_TYPE2, D.TRADE_ID FINPROD_MARKET_ID, D.TRADE_ID FINPROD_ABBR, E.VDATE, E.VDATE TRADE_DATE, E.MDATE, E.BASIS, E.INT_RATE RANGE_YIELD, F.COUNTER_NAME ISSUER, D.CCY, case when D.FINPROD_TYPE2 in ('F08','F02','F04') then -1*A.AMOUNT else A.AMOUNT end as AMOUNT, TEMP_DEPT_CODE.DEPT_CODE FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN PTL_SEC_POSITION_FLOW C ON C.FINPROD_ID = A.FINPROD_ID AND C.PORTFOLIO_ID = A.PORTFOLIO_ID INNER JOIN TRD_PRODUCT_DEAL D ON D.TRADE_ID = C.TRADE_ID AND D.FINPROD_TYPE2 in ('F02','F03','F04','F05','F08','F09') INNER JOIN FIN_TRADE_PRODUCT E ON E.FINPROD_ID = D.TRADE_ID
LEFT JOIN MST_COUNTER_PARTY F ON F.COUNTER_ID = D.COUNTER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND D.FINPROD_TYPE2 in
#{item}
) AA GROUP BY AA.PORTFOLIO_ID, AA.FINPROD_ID, AA.PORTFOLIO_NAME, AA.FINPROD_TYPE2, AA.FINPROD_MARKET_ID, AA.FINPROD_ABBR, AA.VDATE, AA.MDATE, AA.TRADE_DATE, AA.BASIS, AA.RANGE_YIELD, AA.ISSUER, AA.CCY, AA.DEPT_CODE
union all SELECT A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6 TYPE_4, D.TYPE_7 TYPE_5, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, '' BASIS, E.CUSTOMER_NAME ISSUER, C.CCY, NULL RANGE_YIELD, NULL TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE, SUM( A.AMOUNT ) AMOUNT, '02' hasChildren, CONCAT(CONCAT(nvl(A.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl(D.TYPE_6,'null'),'_'),nvl(D.TYPE_7,'null')))) childInfo, CONCAT(CONCAT(A.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),nvl(D.TYPE_6,'null'))) parentInfo FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 = 'F06' INNER JOIN FIN_PRODUCT_TYPE D ON C.FINPROD_ID = D.FINPROD_ID
LEFT JOIN TEMP_CLOSE_PRICE TEMP_CLOSE_PRICE ON TEMP_CLOSE_PRICE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_CLOSE_PRICE.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO E ON C.ISSUER = E.CUSTOMER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND C.FINPROD_TYPE2 in
#{item}
AND D.TYPE_6 in
#{item}
AND D.TYPE_7 in
#{item}
GROUP BY A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6, D.TYPE_7, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, E.CUSTOMER_NAME, C.CCY, C.VDATE, C.MDATE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE
union all select AA.PORTFOLIO_ID, AA.FINPROD_ID, AA.PORTFOLIO_NAME, AA.FINPROD_TYPE2, AA.TYPE_6 TYPE_4, AA.TYPE_7 TYPE_5, AA.FINPROD_MARKET_ID, AA.FINPROD_ABBR, case when AA.PROFIT_TYPE ='01' then null else AA.VDATE end VDATE, case when AA.PROFIT_TYPE ='01' then null else AA.MDATE end MDATE, case when AA.PROFIT_TYPE ='01' then null else AA.BASIS end BASIS, AA.ISSUER, AA.CCY, case when AA.PROFIT_TYPE ='01' then null else AA.RANGE_YIELD end RANGE_YIELD, case when AA.PROFIT_TYPE ='01' then null else AA.TRADE_DATE end TRADE_DATE, AA.DEPT_CODE, AA.CLOSE_PRICE, AA.AMOUNT, '02' hasChildren, CONCAT(CONCAT(nvl(AA.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(AA.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl(AA.TYPE_6,'null'),'_'),nvl(AA.TYPE_7,'null')))) childInfo, CONCAT(CONCAT(AA.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(AA.FINPROD_TYPE2,'null'),'_'),nvl(AA.TYPE_6,'null'))) parentInfo from ( SELECT A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, C.PROFIT_TYPE, D.TYPE_6, D.TYPE_7, C.VDATE, C.MDATE, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, F.BASIS, G.CUSTOMER_NAME ISSUER, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE, SUM( A.AMOUNT ) AMOUNT FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 in ('F17') INNER JOIN FIN_PRODUCT_TYPE D ON C.FINPROD_ID = D.FINPROD_ID INNER JOIN FIN_CASH_INFO E ON E.CASH_TYPE_2 = 'C02' INNER JOIN FIN_CASH_CALC_RULE F ON E.CASH_ID = F.CASH_ID AND F.EFF_DATE = C.VDATE LEFT JOIN TEMP_RANGE_YIELD TEMP_RANGE_YIELD ON TEMP_RANGE_YIELD.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_RANGE_YIELD.FINPROD_ID = A.FINPROD_ID
LEFT JOIN TEMP_LAST_MDATE TEMP_LAST_MDATE ON TEMP_LAST_MDATE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_LAST_MDATE.FINPROD_ID = A.FINPROD_ID LEFT JOIN TEMP_CLOSE_PRICE TEMP_CLOSE_PRICE ON TEMP_CLOSE_PRICE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_CLOSE_PRICE.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO G ON C.ISSUER = G.CUSTOMER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND C.FINPROD_TYPE2 in
#{item}
AND D.TYPE_6 in
#{item}
AND D.TYPE_7 in
#{item}
GROUP BY A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6, D.TYPE_7, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, G.CUSTOMER_NAME, C.CCY, C.PROFIT_TYPE, TEMP_DEPT_CODE.DEPT_CODE, TEMP_CLOSE_PRICE.CLOSE_PRICE, TEMP_LAST_MDATE.TRADE_DATE, TEMP_RANGE_YIELD.RANGE_YIELD ) AA
union all SELECT A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6, D.TYPE_7, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, G.CUSTOMER_NAME ISSUER, C.CCY, TEMP_RANGE_YIELD.RANGE_YIELD, TEMP_LAST_MDATE.TRADE_DATE, TEMP_DEPT_CODE.DEPT_CODE, null CLOSE_PRICE, SUM( A.AMOUNT ) AMOUNT , '02' hasChildren, CONCAT(CONCAT(nvl(A.PORTFOLIO_ID,'null'),'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),CONCAT(CONCAT(nvl(D.TYPE_6,'null'),'_'),nvl(D.TYPE_7,'null')))) childInfo, CONCAT(CONCAT(A.PORTFOLIO_ID,'_'),CONCAT(CONCAT(nvl(C.FINPROD_TYPE2,'null'),'_'),nvl(D.TYPE_6,'null'))) parentInfo FROM PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 in ('F18') INNER JOIN FIN_PRODUCT_TYPE D ON C.FINPROD_ID = D.FINPROD_ID INNER JOIN FIN_CASH_INFO E ON E.CASH_TYPE_2 = 'C02' INNER JOIN FIN_CASH_CALC_RULE F ON E.CASH_ID = F.CASH_ID AND F.EFF_DATE = C.VDATE LEFT JOIN TEMP_RANGE_YIELD TEMP_RANGE_YIELD ON TEMP_RANGE_YIELD.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_RANGE_YIELD.FINPROD_ID = A.FINPROD_ID LEFT JOIN TEMP_DEPT_CODE TEMP_DEPT_CODE ON TEMP_DEPT_CODE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_DEPT_CODE.FINPROD_ID = A.FINPROD_ID LEFT JOIN TEMP_LAST_MDATE TEMP_LAST_MDATE ON TEMP_LAST_MDATE.PORTFOLIO_ID = A.PORTFOLIO_ID AND TEMP_LAST_MDATE.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO G ON C.ISSUER = G.CUSTOMER_ID WHERE A.HODING_TYPE = '03' and A.CDATE = TO_DATE(#{queryDate},'yyyy-MM-dd')
AND A.PORTFOLIO_ID in
null) OR A.PORTFOLIO_ID in (
#{item}
AND A.FINPROD_ID in
#{item}
AND C.FINPROD_TYPE2 in
#{item}
AND D.TYPE_6 in
#{item}
AND D.TYPE_7 in
#{item}
GROUP BY A.PORTFOLIO_ID, C.FINPROD_ID, B.PORTFOLIO_NAME, C.FINPROD_TYPE2, D.TYPE_6, D.TYPE_7, C.FINPROD_MARKET_ID, C.FINPROD_ABBR, C.VDATE, C.MDATE, F.BASIS, G.CUSTOMER_NAME, C.CCY, TEMP_DEPT_CODE.DEPT_CODE, TEMP_LAST_MDATE.TRADE_DATE, TEMP_RANGE_YIELD.RANGE_YIELD

